 if(!im.complete||!im.naturalWidth){ctx.fillStyle="#EEF4F8";ctx.font="18px sans-serif";ctx.fillText(lang==="es"?"Preparando la pieza…":"Preparing the piece…",24,38);return}
 const r=M.imageRect(im,W,H,state().cam);ctx.save();ctx.globalAlpha=.98;ctx.drawImage(im,r.x,r.y,r.w,r.h);ctx.restore();drawCover(im,r);
