 $("observe").disabled=!ev.observable;$("identify").disabled=!ev.identifiable||s.identified;$("nextBtn").disabled=active>=P.encounters.length-1;
 say(statusFromEval(ev),ev.identifiable||s.identified?"good":ev.offscreenRequired?"warn":"")
