 $("journalBtn").childNodes[0].nodeValue=tr("journal")+" ";$("helpBtn").textContent=tr("help");$("title").textContent=tr("title");$("lead").textContent=tr("lead");document.querySelector('label[for="encounter"]').textContent=tr("encounter");
 $("exploreMode").textContent=tr("explore");$("brushMode").textContent=tr("brush");$("clearPoint").textContent=tr("clear");$("observe").textContent=tr("observe");$("guide").textContent=tr("guide");$("identify").textContent=tr("identify");$("sceneHelp").textContent=tr("sceneHelp");$("observationKicker").textContent=tr("observation");$("depthBtn").textContent=tr("depth");$("nextBtn").textContent=tr("next");document.querySelector(".secondary-info summary").textContent=tr("prep");$("simulationCopy").textContent=tr("simulation");$("sourcesBtn").textContent=tr("sources");$("closeDialog").textContent=tr("close");
