 $("encounterStep").textContent=(active+1)+" / "+P.encounters.length;$("encounterTitle").textContent=tx(encounter().title);$("encounterClue").textContent=tx(encounter().clue);$("journalCount").textContent=journal.size;
 [...$("encounter").options].forEach((o,i)=>o.textContent=(i+1)+" · "+tx(P.encounters[i].title));$("encounter").value=String(active);updateObservation();render()
