function setMode(next){mode=next;$("exploreMode").setAttribute("aria-pressed",String(mode==="explore"));$("brushMode").setAttribute("aria-pressed",String(mode==="brush"));$("modeBadge").textContent=mode==="explore"?tr("modeExplore"):tr("modeBrush");if(mode==="brush"&&!state().point)state().point={x:.5,y:.5};updateObservation();render();cv.focus({preventScroll:true})}
function local(ev){const r=cv.getBoundingClientRect();return{x:ev.clientX-r.left,y:ev.clientY-r.top}}
function normFromLocal(p){return M.toNorm(p.x,p.y,asset(encounter().id),W,H,state().cam)}
function pointVisible(p){if(!p)return false;const im=asset(encounter().id),q=M.toScreen(p.x,p.y,im,W,H,state().cam);return M.onImage(p)&&q.x>=12&&q.x<=W-12&&q.y>=12&&q.y<=H-12}
function selectPoint(p){if(!M.onImage(p)){say(tr("outside"),"warn");return false}state().point={x:M.clamp(p.x,0,1),y:M.clamp(p.y,0,1)};say(tr("selected"));render();return true}
function clearAt(p){if(!pointVisible(p)){say(tr("outside"),"warn");return false}state().strokes.push({x:p.x,y:p.y,r:P.brushRadius});state().point={...p};updateObservation();render();return true}
function observe(){const ev=evaluation();if(!ev.observable){say(tr("observeNeed"),"warn");return}for(const z of ev.zones.filter(z=>z.visible))state().observed.add(z.id);updateObservation();live(ev.zones.filter(z=>z.visible).map(z=>tx(z.observation)).join(" "))}
function identify(){const ev=evaluation();if(!ev.identifiable){say(ev.offscreenRequired?tr("offscreen"):tr("identifyNeed"),"warn");return}state().identified=true;journal.add(encounter().id);for(const z of ev.zones.filter(z=>z.visible))state().observed.add(z.id);updateObservation();live(tx(encounter().identity.name)+". "+tx(encounter().identity.text))}
function guide(){const ev=evaluation();let z=ev.zones.find(z=>encounter().requiredZones.includes(z.id)&&!z.visible);if(!z)z=ev.zones.find(z=>encounter().requiredZones.includes(z.id));if(!z)return;state().point={x:z.center[0],y:z.center[1]};guideZone=z.id;guideUntil=Date.now()+2600;const im=asset(encounter().id),q=M.toScreen(z.center[0],z.center[1],im,W,H,state().cam);if(q.x<40||q.x>W-40||q.y<40||q.y>H-40){state().cam.cx=z.center[0];state().cam.cy=z.center[1]}say(tr("guideMsg"));render();setTimeout(()=>{if(Date.now()>=guideUntil){guideZone=null;render()}},2700)}
function openDialog(title){origin=document.activeElement;$("dialogTitle").textContent=title;$("dialogBody").replaceChildren();dialog.showModal();$("closeDialog").focus()}
