function depth(){if(!state().identified)return;openDialog(tx(encounter().identity.name));const wrap=document.createElement("div");wrap.className="depth-grid";const left=document.createElement("div"),im=document.createElement("img");im.src=piece().asset;im.alt=tx(piece().conserva);left.append(im);const right=document.createElement("div"),p1=document.createElement("p");p1.textContent=tx(encounter().identity.text);const p2=document.createElement("p");p2.className="muted";p2.textContent=tx(encounter().identity.limit);const dl=document.createElement("dl");for(const [a,b] of [[lang==="es"?"Se conserva":"Preserved",tx(piece().conserva)],[lang==="es"?"Edad":"Age",tx(piece().edad)],[lang==="es"?"Referencia de procedencia":"Reference context",tx(piece().ref)]]){const dt=document.createElement("dt"),dd=document.createElement("dd");dt.textContent=a;dd.textContent=b;dl.append(dt,dd)}right.append(p1,p2,dl);wrap.append(left,right);$("dialogBody").append(wrap)}
function showSources(){openDialog(tr("sourcesTitle"));const p=document.createElement("p");p.textContent=tx(encounter().identity.limit);$("dialogBody").append(p);const ul=document.createElement("ul");ul.className="source-list";for(const s of encounter().sources){const li=document.createElement("li"),a=document.createElement("a");a.href=s.url;a.textContent=s.title;const small=document.createElement("div");small.className="muted";small.textContent=(lang==="es"?"Consultado: ":"Consulted: ")+s.consulted+" · "+s.supports;li.append(a,small);ul.append(li)}$("dialogBody").append(ul)}
function showHelp(){openDialog(tr("helpTitle"));const ol=document.createElement("ol");for(const x of tr("helpBody")){const li=document.createElement("li");li.textContent=x;ol.append(li)}const p=document.createElement("p");p.className="muted";p.textContent=tr("session");$("dialogBody").append(ol,p)}
function showJournal(){openDialog(tr("journal"));if(!journal.size){const p=document.createElement("p");p.textContent=tr("emptyJournal");$("dialogBody").append(p);return}const host=document.createElement("div");host.className="journal-list";for(const e of P.encounters.filter(x=>journal.has(x.id))){const c=document.createElement("div");c.className="journal-card";const h=document.createElement("h3"),p=document.createElement("p");h.textContent=tx(e.identity.name);p.textContent=tx(e.identity.text);c.append(h,p);host.append(c)}$("dialogBody").append(host)}
function enter(i){active=M.clamp(i,0,P.encounters.length-1);mode="explore";guideZone=null;asset(encounter().id).onload=()=>{fit();sync()};$("encounter").value=String(active);sync();fit()}
function movePoint(dx,dy){const im=asset(encounter().id);let p=state().point||{x:.5,y:.5},q=M.toScreen(p.x,p.y,im,W,H,state().cam);q.x=M.clamp(q.x+dx,28,W-28);q.y=M.clamp(q.y+dy,28,H-28);p=M.toNorm(q.x,q.y,im,W,H,state().cam);state().point={x:M.clamp(p.x,0,1),y:M.clamp(p.y,0,1)};updateObservation();render()}
cv.addEventListener("pointerdown",ev=>{if(ev.button!==0)return;if(gesture)return;const p=local(ev);cv.focus({preventScroll:true});cv.setPointerCapture(ev.pointerId);gesture={id:ev.pointerId,start:p,last:p,moved:false,mode,camera:{...state().cam},changes:0}});
